import {
  InputHTMLAttributes,
  LabelHTMLAttributes,
  ReactNode,
  SelectHTMLAttributes,
  TextareaHTMLAttributes,
} from 'react';
import { cn } from './cn';

const inputBase =
  'w-full rounded-ds border border-line2 bg-surface px-2.5 py-2 text-base text-tx outline-none placeholder:text-tx4 focus:border-tx3';

export function Input(props: InputHTMLAttributes<HTMLInputElement>) {
  return <input {...props} className={cn(inputBase, props.className)} />;
}

export function Textarea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea {...props} className={cn(inputBase, 'min-h-[96px] resize-y leading-relaxed', props.className)} />;
}

export function Select(props: SelectHTMLAttributes<HTMLSelectElement>) {
  return (
    <select
      {...props}
      className={cn(
        inputBase,
        // seta customizada via bg, sem depender de estilo nativo do browser
        "appearance-none bg-[length:5px_5px] bg-no-repeat pr-8 bg-[position:calc(100%-16px)_50%,calc(100%-11px)_50%]",
        props.className,
      )}
    />
  );
}

export interface FieldProps {
  label: string;
  hint?: string;
  children: ReactNode;
  htmlFor?: string;
}

/** Envelope label + input + hint, usado em todos os formulários (Agentes, Config, Agenda). */
export function Field({ label, hint, children, htmlFor }: FieldProps) {
  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={htmlFor} className="text-base font-medium text-tx">
        {label}
      </label>
      {children}
      {hint && <span className="text-sm text-tx3">{hint}</span>}
    </div>
  );
}

export function Switch({
  checked,
  onChange,
  children,
}: {
  checked: boolean;
  onChange: (v: boolean) => void;
  children: ReactNode;
}) {
  return (
    <label className="inline-flex cursor-pointer items-center gap-2.5 text-base text-tx2">
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        className="peer hidden"
      />
      <span className="relative h-[18px] w-[30px] flex-none rounded-ds-full bg-line2 transition-colors peer-checked:bg-tx after:absolute after:left-[3px] after:top-[3px] after:h-3 after:w-3 after:rounded-full after:bg-surface after:transition-transform peer-checked:after:translate-x-3" />
      {children}
    </label>
  );
}

/** Grid 2 ou 3 colunas para pares de <Field> — usar em qualquer formulário. */
export function FieldRow({ cols = 2, children }: { cols?: 2 | 3; children: ReactNode }) {
  return <div className={cn('grid gap-4', cols === 2 ? 'grid-cols-2' : 'grid-cols-3')}>{children}</div>;
}
